import pytest
from roman import to_roman, from_roman


class TestToRoman:
    @pytest.mark.parametrize(
        "input_val,expected",
        [
            (1, "I"),
            (4, "IV"),
            (5, "V"),
            (9, "IX"),
            (10, "X"),
            (21, "XXI"),
            (48, "XLVIII"),
            (3999, "MMMCMXCIX"),
        ],
    )
    def test_to_roman_valid(self, input_val, expected):
        assert to_roman(input_val) == expected

    @pytest.mark.parametrize(
        "input_val",
        [0, -1, 4000],
    )
    def test_to_roman_invalid_range(self, input_val):
        with pytest.raises(ValueError) as exc_info:
            to_roman(input_val)
        assert "invalid" in str(exc_info.value).lower()


class TestFromRoman:
    @pytest.mark.parametrize(
        "input_val,expected",
        [
            ("I", 1),
            ("IV", 4),
            ("V", 5),
            ("IX", 9),
            ("X", 10),
            ("XXI", 21),
            ("XLVIII", 48),
            ("MMMCMXCIX", 3999),
        ],
    )
    def test_from_roman_valid(self, input_val, expected):
        assert from_roman(input_val) == expected

    @pytest.mark.parametrize(
        "input_val",
        ["i", "iv", "XLI", "", None, 123],
    )
    def test_from_roman_invalid_input(self, input_val):
