import pytest
from units import to_celsius, to_fahrenheit


class TestToCelsius:
    @pytest.mark.parametrize(
        "fahrenheit,expected",
        [
            (32.0, 0.0),      # freezing point
            (-40.0, -40.0),   # both scales match
            (212.0, 100.0),   # boiling point
            (98.6, 37.0),     # body temperature
            (0.0, -17.8),     # zero F
            (50.0, 10.0),     # mild weather
            (-4.0, -20.0),    # cold day
        ],
    )
    def test_returns_correct_celsius(self, fahrenheit, expected):
        result = to_celsius(fahrenheit)
        assert result == pytest.approx(expected, rel=1e-6)

    def test_handles_negative_values(self):
        """Verify rounding works for negative temperatures."""
        assert to_celsius(-10.0) == -23.3


class TestToFahrenheit:
    @pytest.mark.parametrize(
        "celsius,expected",
        [
            (0.0, 32.0),      # freezing point
            (-40.0, -40.0),   # both scales match
            (100.0, 212.0),   # boiling point
            (37.0, 98.6),     # body temperature
            (15.0, 59.0),     # mild weather
            (-20.0, -4.0),    # cold day
        ],
    )
    def test_returns_correct_fahrenheit(self, celsius, expected):
        result = to_fahrenheit(celsius)
        assert result == pytest.approx(expected, rel=1e-6)

    def test_handles_negative_values(self):
        """Verify rounding works for negative temperatures."""
        assert to_fahrenheit(-10.0) == 14.0

