import pytest
from wordfreq import top_words


class TestTopWords:
    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("hello", 1, [("hello", 1)]),
            ("hello world", 2, [("hello", 1), ("world", 1)]),
            ("hello hello world", 2, [("hello", 2), ("world", 1)]),
            ("a b c a b a", 3, [("a", 3), ("b", 2), ("c", 1)]),
        ],
    )
    def test_basic(self, text, n, expected):
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("a a b b", 2, [("a", 2), ("b", 2)]),
            ("x y z x y z", 2, [("x", 2), ("y", 2)]),
        ],
    )
    def test_ties_alphabetical(self, text, n, expected):
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("don't", 1, [("don't", 1)]),
            ("i'm it's we're", 3, [("i'm", 1), ("it's", 1), ("we're", 1)]),
            ("hello world don't won't", 2, [("don't", 1), ("won't", 1)]),
        ],
    )
    def test_apostrophes_in_words(self, text, n, expected):
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("hello! hello? HELLO.", 1, [("hello", 2)]),
            ("123 abc 456 xyz", 2, [("abc", 1), ("xyz", 1)]),
        ],
    )
    def test_punctuation_and_numbers_skipped(self, text, n, expected):
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("hello'", 0, []),
            ("'world", 1, [("world", 1)]),
            ("' ' ", 1, []),
        ],
    )
    def test_stray_apostrophes_excluded(self, text, n, expected):
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n", [("", 5), ("" , 0), ("abc", 0)],
    )
    def test_empty_or_zero_n(self, text, n):
        assert top_words(text, n) == []

