import pytest
from cli import run
from store import Store


@pytest.fixture
def store():
    """Create a fresh Store instance for each test."""
    return Store()


@pytest.mark.parametrize(
    "line,expected",
    [
        ("set foo bar", "OK"),
        ("set key1 value1", "OK"),
        ("set empty", "OK"),
    ],
)
def test_set_command(store, line, expected):
    """Test the 'set' command returns 'OK'."""
    result = run(store, line)
    assert result == expected


@pytest.mark.parametrize(
    "line,key,value,expected",
    [
        ("get foo", "foo", "bar", "bar"),
        ("get key1", "key1", "value1", "value1"),
        ("get nonexistent", "nonexistent", None, "(nil)"),
    ],
)
def test_get_command(store, line, key, value, expected):
    """Test the 'get' command returns the value or '(nil)'."""
    if value is not None:
        store.set(key, value)
    result = run(store, line)
    assert result == expected


@pytest.mark.parametrize(
    "line,key,expected",
    [
        ("del foo", "foo", "1"),
        ("del key1", "key1", "1"),
        ("del nonexistent", "nonexistent", "0"),
    ],
)
def test_del_command(store, line, key, expected):
    """Test the 'del' command returns '1' if key existed, '0' otherwise."""
    if key != "nonexistent":
        store.set(key, "some_value")
    result = run(store, line)
    assert result == expected


def test_keys_command(store):
    """Test the 'keys' command returns sorted keys joined by spaces."""
    store.set("zebra", "1")
    store.set("apple", "2")
    store.set("banana", "3")
    result = run(store, "keys")
    assert result == "apple banana zebra"


def test_unknown_command(store):
    """Test unknown commands return empty string."""
    result = run(store, "unknown")
    assert result == ""


def test_malformed_command(store):
    """Test malformed commands return empty string."""
    result = run(store, "set")
    assert result == ""


def test_empty_line(store):
    """Test empty line returns empty string."""
    result = run(store, "")
    assert result == ""

